import json,collections,re,sys,unicodedata
def norm(s): return unicodedata.normalize('NFKD',s.upper()).encode('ascii','ignore').decode()
RULES=[
 ('Agua potable y saneamiento',r'ACUEDUCTO|ALCANTARILLADO|AGUA POTABLE|APROVISIONAMIENTO DE AGUA|CULTURA DEL AGUA|SERVICIOS PUBLICOS DOMICILIARIOS'),
 ('Educación',r'EDUCATIV|DOCENTE|EDUCACION|ESTUDIANT|COLEGIO|PEDAGOGIC|ESCOLAR|INSTITUCION EDUCATIVA|RED EDUCATIVA|BIBLIOTEC|LUDOTEC'),
 ('Salud pública',r'SALUD|VACUNACION|ANTIRRABIC|VETERINARI|ESTERILIZACION|EPIDEMIOLOG|TUBERCULOSIS|BIOMEDIC|IPS |HOSPITAL|ENFERMER|MEDIC|ASEGURAMIENTO|ZOONOSIS|VECTORES|FUMIGACION'),
 ('Seguridad, convivencia y justicia',r'SEGURIDAD|FONSET|CONVIVENCIA|POLICIA|CCTV|VIDEOVIGILANCIA|COMISARI|INSPECCION|CARCEL|PENITENCIAR|CRIMINAL|DELITO'),
 ('Movilidad y tránsito',r'TRANSITO|MOVILIDAD|SEÑALIZACION|SENALIZACION|DEMARCACION|GRUA|INMOVILIZAD|SEMAFOR|VIAL '),
 ('Cultura, eventos y promoción de ciudad',r'CULTURA|CULTURAL|ARTISTIC|GOSPEL|FERIA|FIESTAS|TURIS|CIUDAD DESTINO|NAVIDE|EVENTO|PROMOCION DE CIUDAD|PATRIMONIO|MUSICA|DANZA|ARTES'),
 ('Deporte y recreación',r'DEPORT|RECREA|ESCENARIO|PARQUE|CANCHA|JUEGOS'),
 ('Inclusión social y población vulnerable',r'ADULTO MAYOR|HABITANTE DE CALLE|DISCAPACIDAD|VICTIMA|INFANCIA|NIÑ|JUVENTUD|JOVEN|MUJER|GENERO|LGBT|MIGRANT|VULNERAB|SUSTANCIAS PSICO|FAMILIA|INDIGEN|AFRO|POBREZA|EXEQUIAL|HUMANITARI|PAZ|RECONCILIA'),
 ('Infraestructura, vías y espacio público',r'OBRA|CONSTRUCCION|ESPACIO PUBLICO|MALLA VIAL|INFRAESTRUCTURA VIAL|PAVIMENT|MURO|ADECUACION|MANTENIMIENTO DE LA INFRAESTRUCTURA|INTERVENTORIA|PUENTE|ANDEN|URBANISMO|VIVIENDA|PLANEACION|ORDENAMIENTO|POT|CURADURIA|LICENCIA'),
 ('Ambiente y gestión del riesgo',r'AMBIENTAL|ARBOL|PODA|RESIDUOS|RECICL|GESTION DEL RIESGO|EMERGENCIA|DESASTRE|BOMBERO|CAMBIO CLIMATICO|ANIMAL'),
 ('Desarrollo económico y empleo',r'EMPLEO|EMPRENDIM|DESARROLLO ECONOMICO|COMERCI|EMPRESARI|PRODUCTIV|AGRICOL|AGROPECUAR|RURAL|CAMPESIN|CREDITO'),
 ('Hacienda, catastro y finanzas',r'HACIENDA|CATASTR|TRIBUTAR|IMPUEST|RECAUD|FISCAL|DEUDA|PRESUPUEST|CONTABL|FINANCIER|VALORIZACION|CALIFICACION'),
 ('Comunicaciones y medios',r'PRENSA|COMUNICACION|MEDIOS|DIFUSION|PUBLICIDAD|CONTENIDOS|DIVULGACION'),
 ('Gestión jurídica',r'JURIDIC|DERECHO|ABOGAD|DEFENSA JUDICIAL|REPRESENTACION JUDICIAL|PROCESOS JUDICIALES|CONTRATACION ESTATAL'),
 ('Funcionamiento administrativo',r'.'),
]
CR=[(n,re.compile(p)) for n,p in RULES]
def sector(obj):
    o=norm(obj or '')
    for n,c in CR:
        if c.search(o): return n
